typedef unsigned int nslSoundId;
typedef unsigned int nslSourceId;

struct nslSource
{
  bool used;
  char storage[55];
  int bank;
  char tail[36];
};

struct nslSound
{
  char flags[4];
  bool used;
  char storage[47];
  nslSoundId myId;
  nslSourceId mySource;
  char tail[28];
};

struct nslSystem
{
  char listenerPo[64];
  nslSource sourceSlots[512];
  nslSound soundSlots[256];
  char storage[30740];
  unsigned int numBanks;
  char queuedSounds[40];
  int speakerMode;
  int outputMode;
  int language;
  int cdDvdMode;
  unsigned long long lastClock;
  bool on;
};

extern nslSystem nsl;
void nslStopSound(nslSoundId);
void _nslClearSourceSlot(unsigned int, bool);
int nslPs2GasRpc(int, const char *, int, int, int, int);

#define NSL_NUM_SOURCES 512
#define NSL_NUM_SOUNDS 256
#define NSL_SOURCE_SLOT_MASK 0x0000FFFF
#define NSL_GET_SOURCE_SLOT_FROM_ID(x) (x & NSL_SOURCE_SLOT_MASK)
#define GAS_RPC_POP_BANK 0x00f5

bool nslPopBank( )
{
  if (nsl.numBanks == 0)
    return false;
  int src;
  for (int i=0; i < NSL_NUM_SOUNDS; i++)
  {
    src = NSL_GET_SOURCE_SLOT_FROM_ID(nsl.soundSlots[i].mySource);
    if (nsl.sourceSlots[src].used && nsl.soundSlots[i].used && (nsl.sourceSlots[src].bank == nsl.numBanks - 1))
    {
      nslStopSound(nsl.soundSlots[i].myId); 
    }
  }

  for (int i=0; i < NSL_NUM_SOURCES; i++)
  {
    if (nsl.sourceSlots[i].used && nsl.sourceSlots[i].bank == nsl.numBanks - 1)
    {
      _nslClearSourceSlot(i, false); 
    }
  }

  bool retVal = nslPs2GasRpc(GAS_RPC_POP_BANK, 0, 0,0,0,0);

  nsl.numBanks--;
  if (nsl.numBanks == 0 )
    nsl.on = false;
  else
    nsl.on = true;

  return retVal;
}
